"""Shared types for NeuroHear. Frozen contract between acquisition, encoding,
experiment and UI layers.

Units (agreed once, used everywhere):
  * time inside a trial: milliseconds (float) relative to trial t0 = first sample
    of the trial recording window
  * device clock: frames at 25 kHz (cl-sdk convention); *_us fields are microseconds
  * current: microamps (magnitude; biphasic sign generated by the adapter)
  * phase width: microseconds per phase
"""
from __future__ import annotations

from dataclasses import dataclass, field, asdict
from typing import Literal, Protocol, Any
import numpy as np

FS_HZ = 25_000                     # CL1 / cl-sdk frame rate
N_CHANNELS = 64
# CL1 MEA: 0, 7, 56, 63 are unused (grounded) and 4 is the reference channel
# (Cortical Labs CL-00 docs; cl-sdk's random source keeps all five silent).
# They carry no neural signal, so no simulator may put one there and no decoder may read them.
SILENT_CHANNELS = (0, 4, 7, 56, 63)
Label = Literal["YES", "NO"]
LABELS: tuple[str, str] = ("YES", "NO")
Source = Literal["reactive_sim", "sdk_random", "replay", "live_cl1", "cl_sdk_sim"]
Split = Literal["train", "val", "test", "control"]

# Human-facing provenance strings. Every metric shown anywhere carries one.
PROVENANCE = {
    "reactive_sim": "SIMULATED MODEL",
    "sdk_random": "SIMULATED (RANDOM, STIM-INDEPENDENT)",
    "cl_sdk_sim": "SIMULATED MODEL VIA CL-SDK",
    "replay": "RECORDED (REPLAY)",
    "live_cl1": "LIVE CL1",
}
IS_LIVING_TISSUE = {"reactive_sim": False, "sdk_random": False, "cl_sdk_sim": False,
                    "replay": None, "live_cl1": True}


@dataclass(frozen=True)
class StimPulse:
    channel: int
    offset_ms: float          # relative to stimulus onset
    phase_us: int             # per phase; multiple of 20 us
    current_uA: float         # magnitude; adapter makes it biphasic, negative-first

    @property
    def charge_nC(self) -> float:
        # biphasic: two phases each |I| * t
        return 2 * abs(self.current_uA) * self.phase_us / 1000.0


@dataclass
class Trial:
    trial_id: str
    run_id: str
    source: str
    label: str                                  # ground truth; NEVER given to the tissue model
    encoder_id: str
    encoder_params: dict
    stimulus: list[StimPulse]
    stim_onset_ms: float                        # where stimulus offset 0 sits in the recording
    spikes: np.ndarray                          # (n, 2) float: [t_ms, channel]
    duration_ms: float
    response_window_ms: tuple[float, float]
    artifact_intervals_ms: list[tuple[float, float]]
    raw_samples: np.ndarray | None = None       # (samples, channels) float32 uV, optional
    features: np.ndarray | None = None
    pred_label: str | None = None
    pred_prob: float | None = None
    split: str = "train"
    metadata: dict = field(default_factory=dict)

    def summary(self, include_spikes: bool = False, max_spikes: int = 4000) -> dict:
        d = {
            "trial_id": self.trial_id, "run_id": self.run_id, "source": self.source,
            "provenance": PROVENANCE.get(self.source, self.source),
            "label": self.label, "encoder_id": self.encoder_id,
            "encoder_params": self.encoder_params,
            "stimulus": [asdict(p) for p in self.stimulus],
            "stim_onset_ms": self.stim_onset_ms, "duration_ms": self.duration_ms,
            "response_window_ms": list(self.response_window_ms),
            "artifact_intervals_ms": [list(x) for x in self.artifact_intervals_ms],
            "pred_label": self.pred_label, "pred_prob": self.pred_prob,
            "split": self.split, "n_spikes": int(len(self.spikes)),
            "metadata": self.metadata,
        }
        if include_spikes:
            s = self.spikes[:max_spikes]
            d["spikes"] = [[round(float(t), 2), int(c)] for t, c in s]
        return d


@dataclass
class Acquisition:
    """What a backend returns for one stimulation trial. Deliberately contains
    no label / encoder information: backends only ever see pulse events."""
    spikes: np.ndarray                    # (n, 2) [t_ms, channel], t relative to recording start
    duration_ms: float
    stim_onset_ms: float
    raw_samples: np.ndarray | None = None
    delivered: list[StimPulse] = field(default_factory=list)
    metadata: dict = field(default_factory=dict)


class NeuralBackend(Protocol):
    """Hardware abstraction layer. NOTE: run_trial receives pulses only — no
    label, no encoder id, no optimiser score. This is the structural guarantee
    against label leakage into simulated responses."""
    source: str

    def get_status(self) -> dict: ...
    def connect(self) -> None: ...
    def run_trial(self, pulses: list[StimPulse]) -> Acquisition: ...
    def close(self) -> None: ...


def jsonable(o: Any) -> Any:
    """Recursively convert numpy types for JSON export."""
    if isinstance(o, dict):
        return {str(k): jsonable(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [jsonable(v) for v in o]
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (np.floating,)):
        return float(o)
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, np.bool_):
        return bool(o)
    return o
